const PIPELINE_VENTAS = 12677012;
const PIPELINE_RECURRENTES = 12676956;
const STAGE_WON_ID = 142;
const FIELD_BUDGET_CODE = 'budget';
const leads = items.flatMap(i => i.json._embedded?.leads ?? []);
function obtenerPresupuesto(lead) {
  const fields = lead.custom_fields_values ?? [];
  return fields.find(f => String(f.field_code ?? '').toLowerCase() === FIELD_BUDGET_CODE) ?? null;
}
function parsePrecio(valor) {
  if (valor === null || valor === undefined) return null;
  const s = String(valor).trim();
  if (s === '') return null;
  const tieneComa = s.includes(',');
  const tienePunto = s.includes('.');
  let n;
  if (tieneComa && tienePunto) {
    if (s.lastIndexOf(',') > s.lastIndexOf('.')) { n = Number(s.split('.').join('').replace(',', '.')); }
    else { n = Number(s.split(',').join('')); }
  } else if (tieneComa) {
    const partes = s.split(',');
    const esMiles = partes.slice(1).every(p => p.length === 3) && partes[0].length <= 3;
    n = esMiles ? Number(partes.join('')) : Number(s.replace(',', '.'));
  } else { n = Number(s); }
  return Number.isFinite(n) ? n : null;
}
let suma = 0;
let countWon = 0;
let sinPrecio = 0;
for (const lead of leads) {
  if (lead.pipeline_id !== PIPELINE_VENTAS && lead.pipeline_id !== PIPELINE_RECURRENTES) continue;
  if (lead.status_id !== STAGE_WON_ID) continue;
  countWon++;
  const precio = parsePrecio(obtenerPresupuesto(lead)?.values?.[0]?.value);
  if (precio === null) { sinPrecio++; continue; }
  suma += precio;
}
const promedio = countWon > 0 ? suma / countWon : 0;
const formatear = n => '$' + n.toLocaleString('es-EC', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
return [{ json: { text_main: formatear(promedio), text_sub: String(countWon) + ' ventas ganadas', raw_sum: suma, raw_won: countWon, raw_sin_precio: sinPrecio, raw_avg: promedio } }];
